        <div class="register-table-wrap"><table class="table register-table accounting-table" data-table-static><thead><tr><th scope="col">Ordine e causale</th><th scope="col">Data e operatore</th><th scope="col" class="text-end">Effetto contabile</th><th scope="col">Tipo e cassa</th></tr></thead><tbody>@forelse($entries as $payment)<tr><td><a class="register-primary" href="{{ route('orders.show', $payment->order) }}">{{ $payment->order->reference }}</a>@if($payment->note)<span class="register-note">{{ $payment->note }}</span>@endif</td><td>{{ $payment->created_at->timezone('Europe/Rome')->format('d/m/Y H:i') }}<small class="register-note">{{ $payment->user->name }}</small></td><td class="text-end"><x-ui.signed-money :amount="$payment->amount_cents" /></td><td><span class="status-pill {{ ($payment->amount_cents < 0 || ($payment->cash_amount_cents ?? $payment->amount_cents) < 0) ? 'tone-danger' : 'tone-green' }}">{{ $payment->label() }}</span><small class="register-note">Cassa: <x-ui.signed-money :amount="$payment->cash_amount_cents ?? $payment->amount_cents" /></small>@if($payment->originalEntry)<a class="register-note" href="{{ route('audits.index', ['type' => 'payment_entries', 'slug' => $payment->originalEntry->slug]) }}">Movimento originale</a>@endif</td></tr>@empty<tr><td colspan="4" class="register-empty">Nessun movimento registrato.</td></tr>@endforelse</tbody></table></div>{{ $entries->links('components.ui.pagination', ['compact' => true]) }}
